head.script:
scwin.gVar = {
    "cTooltip": "",
    "cTooltipDisplay": "",
    "cTooltipFormatter": "",
    "cTooltipLocaleRef": "",
    "cUseLocale": "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textbox > P > tooltipFormatter]<br/>툴팁 내용을 동적으로 생성하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [        
        "툴팁 내용을 생성할 사용자 정의 함수를 설정할 수 있어야 합니다.",     
        "tooltip, tooltipDisplay 속성에 의한 툴팁 모두에 적용되어야 합니다.",
        "사용자 정의 함수는 렌더링 시 지정된 ID 와 기존 툴팁 텍스트 두 가지 정보를 파라미터로 받아야 합니다.",     
        "사용자 정의 함수의 반환값이 새로운 툴팁 텍스트로 적용되어야 합니다.",
        "tooltip 속성을 설정하지 않으면 tooltipFormatter 속성은 무시되어야 합니다.",
        "useLocale, tooltipLocalRef 속성을 설정하지 않으면 사용자 정의 함수의 파라미터에 tooltip 속성값이 전달되어야 합니다.",
        "useLocale, tooltipLocalRef 속성을 설정하면 사용자 정의 함수의 파라미터에 tooltipLocalRef 의 Value 값이 전달되어야 합니다.",
        "tooltipDisplay 속성의 툴팁이면 사용자 정의 함수의 파라미터에 컴포넌트의 내부 텍스트가 전달되어야 합니다.",
    ]
} 



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        tooltip: scwin.gVar["cTooltip"],
        tooltipDisplay: scwin.gVar["cTooltipDisplay"],
        tooltipFormatter: scwin.gVar["cTooltipFormatter"],
        tooltipLocaleRef: scwin.gVar["cTooltipLocaleRef"],
        useLocale: scwin.gVar["cUseLocale"],
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';    
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:textbox ' + strNameSpace + ' ' + cList + ' id="" label="abcdefghijklmnopqrstuvwxyz" style="width:150px; height:50px; text-overflow:ellipsis;white-space:nowrap;overflow:hidden; background-color:var(--ws-gray-300);"  ev:onclick="scwin.target1_onclick" ></w2:textbox>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "textbox",
        strTarget,
        grp_comp
    );
}
